\documentclass[article]{standalone}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting,hooks}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepgfplotslibrary{groupplots}
\usepackage{fontspec}
\setmainfont{Arial}

\pagestyle{empty}

% ── Dark Dashboard Color Scheme ──
\definecolor{bgdark}{HTML}{0F172A}        % Deep charcoal
\definecolor{bgcard}{HTML}{1E293B}        % Card background
\definecolor{blueacc}{HTML}{3B82F6}       % Electric blue
\definecolor{tealacc}{HTML}{14B8A6}       % Teal
\definecolor{amberacc}{HTML}{F59E0B}      % Warm amber
\definecolor{white}{HTML}{FFFFFF}
\definecolor{lightgray}{HTML}{94A3B8}
\definecolor{darkgray}{HTML}{475569}
\definecolor{redacc}{HTML}{EF4444}
\definecolor{greenacc}{HTML}{22C55E}

\pagecolor{bgdark}
\color{white}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={6pt}{0pt}{blueacc},
    left=20pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{blueacc},
    coltitle=blueacc, colbacktitle=bgcard!90!blueacc,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=3pt, titlerule style={blueacc!60},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={6pt}{0pt}{tealacc},
    left=20pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{tealacc},
    coltitle=tealacc, colbacktitle=bgcard!90!tealacc,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=3pt, titlerule style={tealacc!60},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={6pt}{0pt}{amberacc},
    left=20pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{amberacc},
    coltitle=amberacc, colbacktitle=bgcard!90!amberacc,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=3pt, titlerule style={amberacc!60},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=blueacc!20!bgcard,
    borderline west={8pt}{0pt}{blueacc},
    left=20pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=blueacc,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3,color=black},
  },
}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth,height=#1\linewidth,keepaspectratio]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{lightgray}\textit{#3}}\vspace{2mm}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════════
% TITLE BAR (rows 1-4)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, colframe=bgdark, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4,color=blueacc},
  borderline south={4pt}{0pt}{blueacc!40},
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\color{white} FRONTIER AI MODELS}\\[10pt]
  {\fontsize{52}{62}\selectfont\bfseries\color{blueacc} Intelligence, Speed \& Cost}\\[12pt]
  {\fontsize{28}{34}\selectfont\color{lightgray} Based on Artificial Analysis Intelligence Index v4.0}
}

% ═══════════════════════════════════════════════════════════════
% STAT BANNER (rows 4-8) - 5 big callout numbers
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgcard, colframe=bgcard, arc=0pt, boxrule=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
]{name=stats, column=1, span=2, between=row4 and row8}{
  \centering
  \def\statbox#1#2#3#4{%
    \begin{minipage}[c]{0.19\linewidth}\centering
      \colorbox{bgdark!85!#3}{%
        \parbox{0.92\linewidth}{%
          \centering\vspace{8pt}%
          {\fontsize{56}{68}\selectfont\bfseries\color{#3} #1}\\[4pt]
          {\fontsize{18}{22}\selectfont\color{lightgray} #2}\\[2pt]
          {\fontsize{14}{17}\selectfont\color{#3!70!white} #4}\vspace{8pt}%
        }%
      }%
    \end{minipage}%
  }%
  \statbox{57}{Intelligence Leaders}{blueacc}{Gemini 3.1 Pro \& GPT-5.4 (tied)}%
  \hfill\statbox{206}{tokens/sec Speed}{tealacc}{gpt-oss-120B (high) leads}%
  \hfill\statbox{\$0.30}{Lowest Price}{greenacc}{gpt-oss \& DeepSeek V3.2}%
  \hfill\statbox{\$10.00}{Highest Price}{redacc}{Claude Opus 4.6 (max)}%
  \hfill\statbox{33×}{Price Range Factor}{amberacc}{Budget to Premium gap}%
}

% ═══════════════════════════════════════════════════════════════
% INTELLIGENCE RANKINGS (Column 1, rows 8-13)
% ═══════════════════════════════════════════════════════════════
\posterbox[darkcard, title={Intelligence Index (AA v4.0)}
]{name=intelligence, column=1, between=row8 and row13}{
  \fontsize{30}{38}\selectfont
  \begin{tikzpicture}[scale=0.95,transform shape]
    \begin{axis}[
      ybar,
      width=0.95\linewidth,
      height=140mm,
      bar width=6mm,
      ymin=25, ymax=60,
      xtick={1,...,11},
      xticklabels={gpt-oss,Nemotron,DeepSeek,G3Flash,Grok4,GLM-5,Muse,Sonet4,Opus4,GPT-5,G3Pro},
      xticklabel style={rotate=45, anchor=east, font=\fontsize{16}{20}\selectfont\color{lightgray}, yshift=-2mm},
      ytick style={draw=none},
      axis x line=none,
      axis y line=left,
      grid=major,
      grid style={darkgray!40},
      major grid style={line width=0.5pt},
      tickwidth=0pt,
      enlargelimits=0.08,
      scatter/@pre marker code/.style={},scatter/@post marker code/.style={},
    ]
    \addplot[fill=blueacc!80!bgcard, draw=blueacc] coordinates {
      (1,33)(2,36)(3,42)(4,46)(5,49)(6,51)(7,52)(8,52)(9,53)(10,57)(11,57)
    };
    \end{axis}
  \end{tikzpicture}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray}\textit{Ranked by AA Intelligence Index — Top models tied at 57}}
}

% ═══════════════════════════════════════════════════════════════
% SPEED VS COST (Column 2, rows 8-13)
% ═══════════════════════════════════════════════════════════════
\posterbox[tealcard, title={Speed vs Cost Trade-Off}
]{name=speedcost, column=2, between=row8 and row13}{
  \fontsize{30}{38}\selectfont
  \begin{tikzpicture}[scale=0.95,transform shape]
    \begin{axis}[
      width=0.95\linewidth,
      height=140mm,
      xlabel={Speed (tokens/sec)},
      ylabel={Price (\$/1M tokens)},
      xmin=0, xmax=250,
      ymin=0, ymax=12,
      tick label style={font=\fontsize{18}{22}\selectfont\color{lightgray}},
      xlabel style={color=lightgray, font=\fontsize{20}{24}\selectfont},
      ylabel style={color=lightgray, font=\fontsize{20}{24}\selectfont},
      grid=both,
      grid style={darkgray!40},
      major grid style={line width=0.5pt},
      axis line style={darkgray},
      scatter=true,
      mark=*,
      every scatter plot/.style={mark size=8pt},
    ]
    \addplot[scatter,only marks,fill=amberacc,draw=amberacc] coordinates {
      (206,0.30)(193,0.40)(162,3.00)(149,1.10)(129,4.50)(72,5.60)(48,6.00)(40,2.10)(40,10.00)(31,0.30)
    };
    \node[anchor=north, font=\fontsize{14}{17}\selectfont\color{white}] at (axis cs:206,0.30) {gpt-oss};
    \node[anchor=north, font=\fontsize{14}{17}\selectfont\color{white}] at (axis cs:193,0.40) {Nemotron};
    \node[anchor=south, font=\fontsize{14}{17}\selectfont\color{white}] at (axis cs:40,10.00) {Opus4};
    \node[anchor=south, font=\fontsize{14}{17}\selectfont\color{white}] at (axis cs:129,4.50) {G3Pro};
    \node[anchor=north, font=\fontsize{14}{17}\selectfont\color{white}] at (axis cs:149,1.10) {G3Flash};
    \end{axis}
  \end{tikzpicture}\\[4pt]
  {\fontsize{22}{28}\selectfont\color{lightgray}\textit{Fastest ≠ Smartest — Budget tier dominates speed}}\\
  {\fontsize{18}{22}\selectfont\color{amberacc!80!white}\textbf{Key insight:} gpt-oss is 7× faster but ranks last in intelligence}
}

% ═══════════════════════════════════════════════════════════════
% TRADE-OFF ANALYSIS - 2x2 Matrix (rows 13-17)
% ═══════════════════════════════════════════════════════════════
\posterbox[ambercard, title={The Trade-Off Matrix}
]{name=tradeoff, column=1, span=2, between=row13 and row17}{
  \fontsize{28}{36}\selectfont
  \begin{tabular}{p{0.22\linewidth}p{0.22\linewidth}p{0.22\linewidth}p{0.22\linewidth}}
    \centering\arraybackslash
    \rowcolors{1}{bgdark!85!amberacc}{bgdark!90!amberacc}
    \begin{tabular}{p{0.22\linewidth}}
      \centering{\fontsize{26}{32}\selectfont\color{white}\textbf{BEST INTELLIGENCE}}\\[6pt]
      {\fontsize{48}{58}\selectfont\color{blueacc} 57}\\[4pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} Gemini 3.1 Pro Preview}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} GPT-5.4 (xhigh)}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{amberacc!70!white} \$4.50–\$5.60 / 1M tokens}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} Mid-range speed (72–129 tok/s)}
    \end{tabular}
    &
    \centering\arraybackslash
    \begin{tabular}{p{0.22\linewidth}}
      \centering{\fontsize{26}{32}\selectfont\color{white}\textbf{FASTEST SPEED}}\\[6pt]
      {\fontsize{48}{58}\selectfont\color{tealacc} 206}\\[4pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} gpt-oss-120B (high)}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{greenacc!80!white} \$0.30 / 1M tokens}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} Lowest cost by far}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{redacc!80!white} Intelligence: 33 (last place)}
    \end{tabular}
    &
    \centering\arraybackslash
    \begin{tabular}{p{0.22\linewidth}}
      \centering{\fontsize{26}{32}\selectfont\color{white}\textbf{BEST VALUE}}\\[6pt]
      {\fontsize{48}{58}\selectfont\color{greenacc} 46}\\[4pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} Gemini 3 Flash}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{greenacc!70!white} \$1.10 / 1M tokens}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} 149 tok/s speed}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} Strong middle ground}
    \end{tabular}
    &
    \centering\arraybackslash
    \begin{tabular}{p{0.22\linewidth}}
      \centering{\fontsize{26}{32}\selectfont\color{white}\textbf{PREMIUM TIER}}\\[6pt]
      {\fontsize{48}{58}\selectfont\color{redacc} 53}\\[4pt]
      {\fontsize{20}{24}\selectfont\color{lightgray} Claude Opus 4.6 (max)}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{redacc!70!white} \$10.00 / 1M tokens}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} Slowest (40 tok/s)}\\[6pt]
      {\fontsize{16}{20}\selectfont\color{lightgray} Highest intelligence after leaders}
    \end{tabular}
  \end{tabular}
}

% ═══════════════════════════════════════════════════════════════
% FULL DATA TABLE (rows 17-20)
% ═══════════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Complete Model Comparison}
]{name=datatable, column=1, span=2, between=row17 and bottom}{
  \fontsize{24}{30}\selectfont
  \centering
  \rowcolors{1}{bgdark!80!blueacc}{bgcard}
  \begin{tabular}{p{0.32\linewidth}|p{0.12\linewidth}|p{0.18\linewidth}|p{0.18\linewidth}p{0.12\linewidth}}
    \rowcolor{bgdark!90!blueacc}{\fontsize{22}{26}\selectfont\color{white}\textbf{Model}} &
    {\fontsize{22}{26}\selectfont\color{white}\textbf{Score}} &
    {\fontsize{22}{26}\selectfont\color{white}\textbf{Speed (tok/s)}} &
    {\fontsize{22}{26}\selectfont\color{white}\textbf{Price (\$/1M)}} &
    {\fontsize{22}{26}\selectfont\color{white}\textbf{Tier}}\\[4pt]
    Gemini 3.1 Pro Preview & \centering\arraybackslash{\color{blueacc}57} & 129 & \$4.50 & \centering\arraybackslash\color{blueacc}Intel\\
    GPT-5.4 (xhigh) & \centering\arraybackslash{\color{blueacc}57} & 72 & \$5.60 & \centering\arraybackslash\color{blueacc}Intel\\
    Claude Opus 4.6 (max) & \centering\arraybackslash{\color{redacc}53} & 40 & \$10.00 & \centering\arraybackslash\color{redacc}Premium\\
    Muse Spark & \centering\arraybackslash\color{amberacc}52 & — & — & \centering\arraybackslash\color{amberacc}High\\
    Claude Sonnet 4.6 (max) & \centering\arraybackslash\color{amberacc}52 & 48 & \$6.00 & \centering\arraybackslash\color{amberacc}High\\
    GLM-5.1 & \centering\arraybackslash\color{tealacc}51 & 40 & \$2.10 & \centering\arraybackslash\color{tealacc}Value\\
    Grok 4.20 0309 v2 & \centering\arraybackslash\color{tealacc}49 & 162 & \$3.00 & \centering\arraybackslash\color{tealacc}Value\\
    Gemini 3 Flash & \centering\arraybackslash\color{greenacc}46 & 149 & \$1.10 & \centering\arraybackslash\color{greenacc}Value\\
    DeepSeek V3.2 & \centering\arraybackslash\color{greenacc}42 & 31 & \$0.30 & \centering\arraybackslash\color{greenacc}Budget\\
    NVIDIA Nemotron 3 Super & \centering\arraybackslash\color{greenacc}36 & 193 & \$0.40 & \centering\arraybackslash\color{greenacc}Budget\\
    gpt-oss-120B (high) & \centering\arraybackslash\color{lightgray}33 & 206 & \$0.30 & \centering\arraybackslash\color{lightgray}Budget
  \end{tabular}\\[6pt]
  {\fontsize{18}{22}\selectfont\color{lightgray}\textit{Source: Artificial Analysis Intelligence Index v4.0 — 10 evaluations including GDPval-AA, τ²-Bench, Terminal-Bench, SciCode, GPQA Diamond, and more}}
}

\end{tcbposter}
\end{document}

